INSERT INTO `news` (`id`,`title`,`slug`,`excerpt`,`content`,`published_at`,`is_published`,`author_id`) VALUES
(1,'วิทยาลัยพณิชยการบางนาลงนาม MOU ร่วมกับบริษัทเอเจนซี่ดิจิทัลมาร์เก็ตติ้ง','mou-digital-marketing-agency','ลงนามความร่วมมือพัฒนาทักษะการตลาดดิจิทัลให้นักศึกษา','<p>วิทยาลัยพณิชยการบางนาลงนามบันทึกข้อตกลงความร่วมมือกับบริษัทเอเจนซี่ดิจิทัลมาร์เก็ตติ้ง เพื่อพัฒนาทักษะนักศึกษาด้านการตลาดดิจิทัล</p>','2026-06-20 10:00:00',1,1),
(2,'ศึกษาดูงานคลังสินค้าอัตโนมัติ สาขาการจัดการโลจิสติกส์','warehouse-study-visit','นักศึกษา ปวส. เรียนรู้ระบบ WMS จากสถานประกอบการจริง','<p>นักศึกษาสาขาการจัดการโลจิสติกส์เข้าศึกษาดูงานคลังสินค้าอัตโนมัติภายใต้ความร่วมมือกับบริษัทโลจิสติกส์ เอ็กซ์เพรส</p>','2026-05-09 09:00:00',1,1),
(3,'อบรมผู้ประกอบการรุ่นใหม่ ร่วมกับสำนักงานพาณิชย์จังหวัดสมุทรปราการ','young-entrepreneur-training','นักศึกษาจัดทำแผนธุรกิจ 20 กลุ่ม','<p>กิจกรรมอบรมผู้ประกอบการรุ่นใหม่ ให้ความรู้ด้านการตลาดออนไลน์และการจดทะเบียนธุรกิจ</p>','2026-02-21 09:00:00',1,2),
(4,'ลงนามความร่วมมือส่งเสริมการค้าปลีกกับสมาคมการค้าผู้ประกอบการค้าปลีกไทย','retail-association-mou','เชื่อมโยงนักศึกษากับภาคธุรกิจค้าปลีก','<p>วิทยาลัยลงนามความร่วมมือกับสมาคมการค้าผู้ประกอบการค้าปลีกไทย</p>','2025-09-05 13:00:00',1,1),
(5,'Workshop เทคโนโลยีเว็บสมัยใหม่ ร่วมกับ ไอที โซลูชั่น พลัส','web-workshop','นักศึกษาสร้างเว็บไซต์ต้นแบบ 15 ชิ้นงาน','<p>กิจกรรม Workshop โดยวิทยากรจากบริษัทไอที โซลูชั่น พลัส</p>','2025-11-08 09:00:00',1,2),
(6,'แนะแนวศึกษาต่อ ปวส.-ปริญญาตรี ณ มหาวิทยาลัยราชมงคล','tcas-guidance','ศึกษาดูงานและแนะแนวการเทียบโอนหน่วยกิต','<p>นักศึกษา ปวส. 2 ศึกษาดูงานและรับฟังแนวทางการเทียบโอนหน่วยกิต</p>','2025-12-17 09:00:00',1,1);
